/**
 * @name Taint flow from user input to Markup without escaping
 * @description Data flow from potentially untrusted sources to Markup constructor without proper escaping
 * @kind path-problem
 * @problem.severity error
 * @id py/markup-taint-to-constructor
 * @tags security
 *        external/cwe/cwe-079
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module MarkupTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Any parameter or attribute access that could be user input
    source instanceof DataFlow::ParameterNode or
    exists(DataFlow::AttrRead attr | source = attr)
  }

  predicate isSink(DataFlow::Node sink) {
    // Direct Markup construction without escape
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("markupsafe").getMember("Markup").getACall() and
      sink = call.getArg(0)
    )
  }
}

module MarkupTaintFlow = TaintTracking::Global<MarkupTaintConfig>;
import MarkupTaintFlow::PathGraph

from MarkupTaintFlow::PathNode source, MarkupTaintFlow::PathNode sink
where MarkupTaintFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potentially untrusted data flows to Markup constructor from $@.", source.getNode(), "here"
